// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed parameter: an array length and some values; we only need one element to exercise transfer loop.
    // We'll fuzz a uint256 value and an address flag chooser to create tos/vs arrays; the deciding value is whether
    // we pass address(c) (which reference forbids) or some other address (which both allow). The fuzzer gives
    // an address-sized uint to decide.
    function testFuzz_property(uint256 someValue, uint256 addrChooser) public {
        // Keep values wide but sensible
        vm.assume(someValue != 0); // ensure non-zero transfer amount to be meaningful

        address target = address(uint160(addrChooser));

        // Build single-element arrays for tos and vs
        address[] memory tos = new address[](1);
        uint[] memory vs = new uint[](1);
        tos[0] = target;
        vs[0] = someValue;

        // Call transfer and capture whether it returns (ok==true) or reverts (ok==false)
        bool ok;
        try c.transfer(address(c), tos, vs) returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }

        // General rule (single assertion): For the REFERENCE implementation, calling transfer with any inputs
        // where the first argument (contract_address) equals address(c) is not allowed by validAddress and thus
        // cannot return true; we assert that c.transfer(address(c), ...) does NOT return true (ok == false).
        // This holds for all inputs on the reference; the mutant removing the address(this) check can make ok==true
        // for some fuzz inputs, causing this assertion to fail on the buggy version.
        assertTrue(ok == false);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the arrays lengths and one element value; the crucial adversarial actor is c itself
    function testFuzz_property(uint256 len, uint256 val) public {
        // Keep domain wide but sane: limit len to reasonable range so loop doesn't blow gas
        // allow len == 0 as admissible (reference requires tos.length>0 so will revert),
        // but we want to include len>0 cases too; bound keeps it wide.
        uint256 boundedLen = bound(len, 0, 8);

        // build arrays of length boundedLen
        address[] memory tos = new address[](boundedLen);
        uint[] memory vs = new uint[](boundedLen);
        for (uint i = 0; i < boundedLen; i++) {
            // place the counterparty as address(c) for all entries to trigger the difference
            tos[i] = address(c);
            vs[i] = val + i; // vary values but let fuzzer pick val
        }

        bool ok;
        // call transfer with contract_address == address(c). The reference C's modifier forbids this
        // and thus should always revert (ok == false). The mutant that removed the check may allow
        // the call to proceed and return true (ok == true) for some inputs; we assert the reference
        // property that ok is always false.
        try c.transfer(address(c), tos, vs) returns (bool ret) {
            // if it returns we mark ok true
            ok = ret;
        } catch {
            ok = false;
        }

        // Single assertion: reference C always rejects (reverts) when contract_address == address(c)
        // so ok must be false for ALL admissible inputs; the mutant that removed the check can make ok true
        assertTrue(!ok);
    }
}

// No adversarial helper needed: using address(c) as the target exercises the removed check directly.
